// ggml-common.h - the old name of Strata's quant format header, kept as a forwarder so every `#include "ggml-common.h"` keeps working.
//
// The header is include/strata/quant/strata-quant-common.h, generated by tools/gen_quant_header.py from Strata's own type and codebook tables
// (tools/strata_quants.py, tools/strata_quant_tables.py). New code includes that file. The Metal runtime reads the header's TEXT (it cannot
// follow an #include), and the Mac package ships it as metal/strata-quant-common.h plus a full-text copy under this old name.
#include "../../include/strata/quant/strata-quant-common.h"
